import React, { useState, useEffect } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import ApiService from '../../Services/ApiService';

export default function InfluencerReels() {
    const [reels, setReels] = useState([]);
    const [loading, setLoading] = useState(true);
    const [productNames, setProductNames] = useState({}); // Store product names by ID
    const [filters, setFilters] = useState({
        product: '',
        category: '',
        date: ''
    });
    const [allProductNames, setAllProductNames] = useState([]); // For autocomplete
    const [allCategories, setAllCategories] = useState([]); // For autocomplete
    const [productSuggestions, setProductSuggestions] = useState([]);
    const [categorySuggestions, setCategorySuggestions] = useState([]);
    const navigate = useNavigate();

    useEffect(() => {
        // Initialize Lucide icons
        if (window.lucide) {
            window.lucide.createIcons();
        }
        
        loadReels();
        loadAutocompleteData();
    }, []);

    const loadReels = async () => {
        try {
            setLoading(true);
            const response = await ApiService.getInfluencerReels();
            if (response.success) {
                setReels(response.data);
                // Load product names for all reels
                loadProductNames(response.data);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading reels:', error);
            setLoading(false);
        }
    };

    const loadReelsWithFilters = async () => {
        try {
            setLoading(true);
            const response = await ApiService.getInfluencerReels(filters);
            if (response.success) {
                setReels(response.data);
                // Load product names for all reels
                loadProductNames(response.data);
            }
            setLoading(false);
        } catch (error) {
            console.error('Error loading reels:', error);
            setLoading(false);
        }
    };

    const loadAutocompleteData = async () => {
        try {
            // Load all product names for autocomplete
            const productResponse = await ApiService.getAllProductNames();
            if (productResponse.success) {
                setAllProductNames(productResponse.data);
            }
            
            // Load all categories for autocomplete
            const categoryResponse = await ApiService.getCategories();
            if (categoryResponse.success) {
                setAllCategories(categoryResponse.data);
            }
        } catch (error) {
            console.error('Error loading autocomplete data:', error);
        }
    };

    // Function to load product names from the database
    const loadProductNames = async (reelsData) => {
        try {
            // Collect all unique product IDs from all reels
            const allProductIds = new Set();
            reelsData.forEach(reel => {
                if (reel.product_ids && Array.isArray(reel.product_ids)) {
                    reel.product_ids.forEach(id => allProductIds.add(id));
                }
            });

            if (allProductIds.size === 0) return;

            // Fetch real product names from the API
            const response = await ApiService.getProductNamesByIds(Array.from(allProductIds));
            if (response.success) {
                setProductNames(response.data);
            } else {
                // Fallback to placeholder names if API fails
                const productNamesMap = {};
                allProductIds.forEach(id => {
                    productNamesMap[id] = `Product ${id}`;
                });
                setProductNames(productNamesMap);
            }
        } catch (error) {
            console.error('Error loading product names:', error);
            // Fallback to placeholder names if API fails
            const allProductIds = new Set();
            reelsData.forEach(reel => {
                if (reel.product_ids && Array.isArray(reel.product_ids)) {
                    reel.product_ids.forEach(id => allProductIds.add(id));
                }
            });
            
            const productNamesMap = {};
            allProductIds.forEach(id => {
                productNamesMap[id] = `Product ${id}`;
            });
            setProductNames(productNamesMap);
        }
    };

    const getStatusBadge = (status) => {
        switch (status) {
            case 'approved':
                return <span className="badge bg-success">Approved</span>;
            case 'pending':
                return <span className="badge bg-warning">Pending</span>;
            case 'rejected':
                return <span className="badge bg-danger">Rejected</span>;
            default:
                return <span className="badge bg-secondary">Unknown</span>;
        }
    };

    // Function to render product information for a reel
    const renderProductInfo = (productIds) => {
        if (!productIds || productIds.length === 0) {
            return <span className="text-muted">No products</span>;
        }
        
        // Display only the primary product name associated with the reel
        // Based on project requirements, show only the exact product selected for the reel, not related products
        const primaryProductId = productIds[0]; // First product is the primary one selected during upload
        return (
            <div>
                {productNames[primaryProductId] || `Product ${primaryProductId}`}
            </div>
        );
    };

    // Function to calculate reel count per product
    const getReelCountPerProduct = (productId) => {
        // Count how many reels have this product ID
        let count = 0;
        reels.forEach(reel => {
            if (reel.product_ids && reel.product_ids.includes(productId)) {
                count++;
            }
        });
        return count;
    };

    // Function to handle viewing reels for a specific product
    const handleViewReelsForProduct = (productId) => {
        // Navigate to the product reels page
        navigate(`/studio/influencer/product/${productId}/reels`);
    };

    const handleFilter = () => {
        loadReelsWithFilters();
    };

    const handleClearFilter = () => {
        setFilters({
            product: '',
            category: '',
            date: ''
        });
        loadReels();
    };

    // Autocomplete functions
    const handleProductInputChange = (e) => {
        const value = e.target.value;
        setFilters({...filters, product: value});
        
        if (value.length > 1) {
            const suggestions = allProductNames
                .filter(item => item.name.toLowerCase().includes(value.toLowerCase()))
                .slice(0, 5);
            setProductSuggestions(suggestions);
        } else {
            setProductSuggestions([]);
        }
    };

    const handleCategoryInputChange = (e) => {
        const value = e.target.value;
        setFilters({...filters, category: value});
        
        if (value.length > 1) {
            const suggestions = allCategories
                .filter(item => item.name.toLowerCase().includes(value.toLowerCase()))
                .slice(0, 5);
            setCategorySuggestions(suggestions);
        } else {
            setCategorySuggestions([]);
        }
    };

    const handleProductSuggestionClick = (productName) => {
        setFilters({...filters, product: productName});
        setProductSuggestions([]);
    };

    const handleCategorySuggestionClick = (categoryName) => {
        setFilters({...filters, category: categoryName});
        setCategorySuggestions([]);
    };

    const handleProductInputBlur = () => {
        // Delay hiding suggestions to allow for clicks
        setTimeout(() => {
            setProductSuggestions([]);
        }, 150);
    };

    const handleCategoryInputBlur = () => {
        // Delay hiding suggestions to allow for clicks
        setTimeout(() => {
            setCategorySuggestions([]);
        }, 150);
    };

    return (
        <div className="row">
            <div className="col-12">
                <div className="page-title-box d-flex align-items-center justify-content-between">
                    <h4 className="page-title mb-0">My Reels</h4>
                </div>
            </div>

            <div className="col-12">
                <div className="card">
                    <div className="card-header d-flex align-items-center justify-content-between">
                        <h5 className="card-title mb-0">Reels Management</h5>
                        {/* Removed the Upload Reel button as requested */}
                    </div>
                    <div className="card-body">
                        {/* Filter Section */}
                        <div className="row mb-3">
                            <div className="col-md-3 position-relative">
                                <input
                                    type="text"
                                    className="form-control"
                                    placeholder="Filter by product name"
                                    value={filters.product || ''}
                                    onChange={handleProductInputChange}
                                    onBlur={handleProductInputBlur}
                                />
                                {productSuggestions.length > 0 && (
                                    <ul className="list-group position-absolute w-100 mt-1" style={{zIndex: 1000}}>
                                        {productSuggestions.map((item, index) => (
                                            <li 
                                                key={index} 
                                                className="list-group-item list-group-item-action"
                                                onClick={() => handleProductSuggestionClick(item.name)}
                                                style={{cursor: 'pointer'}}
                                            >
                                                {item.name}
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </div>
                            <div className="col-md-3 position-relative">
                                <input
                                    type="text"
                                    className="form-control"
                                    placeholder="Filter by category"
                                    value={filters.category || ''}
                                    onChange={handleCategoryInputChange}
                                    onBlur={handleCategoryInputBlur}
                                />
                                {categorySuggestions.length > 0 && (
                                    <ul className="list-group position-absolute w-100 mt-1" style={{zIndex: 1000}}>
                                        {categorySuggestions.map((item, index) => (
                                            <li 
                                                key={index} 
                                                className="list-group-item list-group-item-action"
                                                onClick={() => handleCategorySuggestionClick(item.name)}
                                                style={{cursor: 'pointer'}}
                                            >
                                                {item.name}
                                            </li>
                                        ))}
                                    </ul>
                                )}
                            </div>
                            <div className="col-md-3">
                                <input
                                    type="date"
                                    className="form-control"
                                    value={filters.date || ''}
                                    onChange={(e) => setFilters({...filters, date: e.target.value})}
                                />
                            </div>
                            <div className="col-md-3">
                                <button 
                                    className="btn btn-primary me-2" 
                                    onClick={handleFilter}
                                >
                                    Filter
                                </button>
                                <button 
                                    className="btn btn-secondary" 
                                    onClick={handleClearFilter}
                                >
                                    Clear
                                </button>
                            </div>
                        </div>
                        
                        {loading ? (
                            <div className="text-center py-5">
                                <div className="spinner-border" role="status">
                                    <span className="visually-hidden">Loading...</span>
                                </div>
                            </div>
                        ) : reels.length === 0 ? (
                            <div className="text-center py-5">
                                <h5>No reels found</h5>
                                <p className="text-muted">Upload your first reel to get started.</p>
                                {/* Removed the Upload Reel button as requested */}
                            </div>
                        ) : (
                            <div className="table-responsive">
                                <table className="table table-hover align-middle mb-0">
                                    <thead>
                                        <tr>
                                            <th>Product Name</th>
                                            <th>Reel Count</th>
                                            <th>Title</th>
                                            <th>Category</th>
                                            <th>Status</th>
                                            <th>Views</th>
                                            <th>Likes</th>
                                            <th>Date</th>
                                            <th>Actions</th>
                                        </tr>
                                    </thead>
                                    <tbody>
                                        {reels.map((reel) => (
                                            <tr key={reel.id}>
                                                <td>
                                                    {renderProductInfo(reel.product_ids)}
                                                </td>
                                                <td>
                                                    {/* Show reel count for the primary product only, not related products */}
                                                    {reel.product_ids && reel.product_ids.length > 0 ? (
                                                        <span className="badge bg-primary">
                                                            {getReelCountPerProduct(reel.product_ids[0])}
                                                        </span>
                                                    ) : (
                                                        <span className="badge bg-secondary">0</span>
                                                    )}
                                                </td>
                                                <td>{reel.title}</td>
                                                <td>{reel.category_name || 'N/A'}</td>
                                                <td>{getStatusBadge(reel.status)}</td>
                                                <td>{reel.views}</td>
                                                <td>{reel.likes}</td>
                                                <td>{new Date(reel.created_at).toLocaleDateString()}</td>
                                                <td>
                                                    {/* Only showing the view button with proper styling */}
                                                    {reel.product_ids && reel.product_ids.length > 0 ? (
                                                        <button 
                                                            className="btn btn-sm btn-info"
                                                            onClick={() => handleViewReelsForProduct(reel.product_ids[0])}
                                                        >
                                                            <i className="ri-eye-line me-1"></i> View
                                                        </button>
                                                    ) : (
                                                        <button 
                                                            className="btn btn-sm btn-secondary"
                                                            disabled
                                                        >
                                                            <i className="ri-eye-line me-1"></i> View
                                                        </button>
                                                    )}
                                                </td>
                                            </tr>
                                        ))}
                                    </tbody>
                                </table>
                            </div>
                        )}
                    </div>
                </div>
            </div>
        </div>
    );
}
